/// <summary>
/// Class entry point. Deletes the SCRIPT data created by XAPI_Setup_EGS_API_newCustomer
/// in reverse dependency order. Only deletes exact, known XAPI test values.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    CustGroupId     custGroupId = 'TST_CstGrp';
    CustPaymMode    paymMode    = 'TST_PaymMd';
    EXU_SystemId    systemId    = 'NewSystem_TC3';

    // --- 1. EXU_ReceivingSystem (delete first: API may have created EXU_ReceivingSystemCust children pointing here; clean those if present) ---
    EXU_ReceivingSystemCust receivingSystemCust;
    EXU_ReceivingSystem     receivingSystem;

    delete_from receivingSystemCust
        where receivingSystemCust.SystemId == systemId;
    info(strFmt("Deleted EXU_ReceivingSystemCust links for SystemId: %1", systemId));

    select firstonly forUpdate receivingSystem
        where receivingSystem.SystemId == systemId;
    if (receivingSystem.RecId)
    {
        receivingSystem.delete();
        info(strFmt("Deleted EXU_ReceivingSystem: %1", systemId));
    }

    // --- 2. CustPaymModeTable (guard: prefix must match testDataPrefix 'TST_') ---
    CustPaymModeTable paymModeTable;

    select firstonly forUpdate paymModeTable
        where paymModeTable.PaymMode == paymMode;
    if (paymModeTable.RecId && strStartsWith(paymModeTable.PaymMode, 'TST_'))
    {
        paymModeTable.delete();
        info(strFmt("Deleted PaymMode: %1", paymMode));
    }

    // --- 3. CustGroup (guard: prefix must match testDataPrefix 'TST_') ---
    CustGroup custGroup;

    select firstonly forUpdate custGroup
        where custGroup.CustGroup == custGroupId;
    if (custGroup.RecId && strStartsWith(custGroup.CustGroup, 'TST_'))
    {
        custGroup.delete();
        info(strFmt("Deleted CustGroup: %1", custGroupId));
    }
}
